/// <summary>
/// designed from AVA
/// </summary>
/// <param name="args">args</param>
[PostHandlerFor(classStr(SalesPurchLineInterface), methodStr(SalesPurchLineInterface, calcLineAmount))]
public static void SalesPurchLineInterface_Post_calcLineAmount(XppPrePostArgs args)
{
    SalesPurchLineInterface     salesPurchLineInterface = args.getThis();
    LineAmount                  lineAmount = args.getReturnValue();

    if (salesPurchLineInterface.parmSalesPurchLine() is SalesLine)
    {
        SalesLine                   salesLine  = salesPurchLineInterface.parmSalesPurchLine();

        AVASpecialDiscSalesLine     specialDiscSalesLine = AVASpecialDiscSalesLine::find(salesLine.InventTransId);

        if (specialDiscSalesLine.RecId)
        {
            if (specialDiscSalesLine.SpecialDiscountPct1 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct1/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct2 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct2/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct3 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct3/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct4 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct4/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct5 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct5/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct6 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct6/100),0.01);
            }
            if (specialDiscSalesLine.SpecialDiscountPct7 > 0)
            {
                lineAmount = lineAmount - round(lineAmount*(specialDiscSalesLine.SpecialDiscountPct7/100),0.01);
            }
        }

        if(salesline.AVAPriceSurchargeCode && salesLine.AVAPriceSurchargePercentage)
        {
            lineAmount = round(lineAmount * (100 + salesLine.AVAPriceSurchargePercentage) / 100, 0.01);
        }
    }

    if (salesPurchLineInterface.parmSalesPurchLine() is SalesQuotationLine)
    {
        SalesQuotationLine      salesQuotationLine = salesPurchLineInterface.parmSalesPurchLine();

        if(salesQuotationLine.AVAPriceSurchargeCode && salesQuotationLine.AVAPriceSurchargePercentage)
        {
            lineAmount = lineAmount * (100 + salesQuotationLine.AVAPriceSurchargePercentage) / 100;
        }

        if (salesQuotationLine.KCS_CRMisAlternativeLine)
        {
            lineAmount = 0;
        }
    }
    args.setReturnValue(lineAmount);

}

/// <summary>
///    AVA <c>SalesPurchLineInterface_Post_calcLineAmountForced</c> method.
/// </summary>
/// <param name="args">
///    <c>XppPrePostArgs</c> as type
/// </param>
[PostHandlerFor(classStr(SalesPurchLineInterface), methodStr(SalesPurchLineInterface, calcLineAmountForced))]
public static void SalesPurchLineInterface_Post_calcLineAmountForced(XppPrePostArgs args)
{
    SalesPurchLineInterface     salesPurchLineInterface;
    LineAmount                  lineAmount;
    SalesLine                   salesLine;
    SalesQuotationLine          salesQuotationLine;

    salesPurchLineInterface = args.getThis();
    lineAmount              = args.getReturnValue();

    if (salesPurchLineInterface.parmSalesPurchLine() is SalesLine)
    {
        salesLine = salesPurchLineInterface.parmSalesPurchLine();

        if(salesline.AVAPriceSurchargeCode && salesLine.AVAPriceSurchargePercentage)
        {
            lineAmount = round(lineAmount * (100 + salesLine.AVAPriceSurchargePercentage) / 100, 0.01);
        }
    }
    else if (salesPurchLineInterface.parmSalesPurchLine() is SalesQuotationLine)
    {
        salesQuotationLine = salesPurchLineInterface.parmSalesPurchLine();

        if(salesQuotationLine.AVAPriceSurchargeCode && salesQuotationLine.AVAPriceSurchargePercentage)
        {
            lineAmount = lineAmount * (100 + salesQuotationLine.AVAPriceSurchargePercentage) / 100;
        }
    }
    args.setReturnValue(lineAmount);
}
